1	export type Item = {
2	  type: string;
3	  material?: string;
4	  cursed?: boolean;
5	  enchantment?: number;
6	};
7	export type Damage = { itemType: string; amount: number };
8	export type Incident = { cause: string; damages: Damage[] };
9	export type QuoteStep = { op: "quote"; items: Item[] };
10	export type ClaimStep = { op: "claim"; policy: number; incident: Incident };
11	export type Step = QuoteStep | ClaimStep;
12	export type Customer = { yearsWithMHPCO: number };
13	export type Scenario = { customer: Customer; steps: Step[] };
14	export type QuoteResult = { premium: number };
15	export type ClaimResult = { payout: number; remainingCap: number };
16	export type Result = QuoteResult | ClaimResult;
17	export type ScenarioOutcome = { results: Result[] };
18	
19	const BASE_PREMIUMS: Record<string, number> = {
20	  sword: 100,
21	  amulet: 60,
22	  staff: 80,
23	  potion: 40,
24	  rune: 25,
25	  moonstone: 25,
26	};
27	
28	const INSURANCE_VALUES: Record<string, number> = {
29	  sword: 1000,
30	  amulet: 600,
31	  staff: 800,
32	  potion: 400,
33	  rune: 250,
34	  moonstone: 250,
35	};
36	
37	const FIRST_INSURANCE_SURCHARGE = 1.1;
38	const PROCESSING_FEE = 5;
39	
40	// Guards against binary-float artifacts (e.g. 52.800000000000004) tipping an
41	// exact value over a whole-gold boundary and inflating the premium by 1 G.
42	const FLOAT_ARTIFACT_PRECISION = 6;
43	
44	const roundUpToWholeGold = (amount: number): number =>
45	  Math.ceil(Number(amount.toFixed(FLOAT_ARTIFACT_PRECISION)));
46	
47	// Multipliers on the base premium, not amounts added to it.
48	const CURSED_RISK_FACTOR = 1.5;
49	const HIGH_ENCHANTMENT_RISK_FACTOR = 1.3;
50	const NO_ADDED_RISK = 1;
51	
52	const HIGH_ENCHANTMENT_LEVEL = 5;
53	
54	const isHighlyEnchanted = (item: Item): boolean =>
55	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
56	
57	// Risks compound: an item that is both cursed and highly enchanted carries
58	// both factors.
59	const riskFactorOf = (item: Item): number =>
60	  (item.cursed ? CURSED_RISK_FACTOR : NO_ADDED_RISK) *
61	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_RISK_FACTOR : NO_ADDED_RISK);
62	
63	// The price-list value adjusted for the item's own risk — not the bare
64	// BASE_PREMIUMS figure.
65	const riskAdjustedPremiumOf = (item: Item): number =>
66	  BASE_PREMIUMS[item.type] * riskFactorOf(item);
67	
68	const BUILDING_BLOCK_SIZE = 3;
69	const BUILDING_BLOCK_PREMIUM = 60;
70	
71	const areAlike = (items: Item[]): boolean =>
72	  items.every((item) => item.type === items[0].type);
73	
74	const sumOfPremiums = (items: Item[]): number =>
75	  items.reduce((total, item) => total + riskAdjustedPremiumOf(item), 0);
76	
77	// An unalike list forms no blocks at all, however many items it holds.
78	const buildingBlockCountOf = (items: Item[]): number =>
79	  areAlike(items) ? Math.floor(items.length / BUILDING_BLOCK_SIZE) : 0;
80	
81	// Alike items group into building blocks priced below the sum of their members'
82	// individual premiums; everything left over prices individually.
83	const blockPricedTotalOf = (items: Item[]): number => {
84	  const blocks = buildingBlockCountOf(items);
85	  const looseItems = items.slice(blocks * BUILDING_BLOCK_SIZE);
86	
87	  return blocks * BUILDING_BLOCK_PREMIUM + sumOfPremiums(looseItems);
88	};
89	
90	const LOYALTY_DISCOUNT_FACTOR = 0.8;
91	const LOYALTY_YEARS = 2;
92	const NO_DISCOUNT = 1;
93	
94	const isLongStanding = (customer: Customer): boolean =>
95	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
96	
97	const loyaltyFactorOf = (customer: Customer): number =>
98	  isLongStanding(customer) ? LOYALTY_DISCOUNT_FACTOR : NO_DISCOUNT;
99	
100	const REPEAT_CONTRACT_DISCOUNT_FACTOR = 0.85;
101	
102	// The first contract carries the initial assessment surcharge; every contract
103	// after it earns the repeat-contract discount instead.
104	const contractFactorOf = (contractIndex: number): number =>
105	  contractIndex === 0 ? FIRST_INSURANCE_SURCHARGE : REPEAT_CONTRACT_DISCOUNT_FACTOR;
106	
107	// Risk factors attach to a single item; these attach to the policy as a whole,
108	// so they multiply the block-priced total once rather than per item.
109	const policyFactorOf = (customer: Customer, contractIndex: number): number =>
110	  contractFactorOf(contractIndex) * loyaltyFactorOf(customer);
111	
112	// The fee is a flat charge on top of the rounded premium, so it sits outside
113	// the rounding rather than being rounded along with it.
114	const premiumFor = (items: Item[], policyFactor: number): number =>
115	  roundUpToWholeGold(blockPricedTotalOf(items) * policyFactor) + PROCESSING_FEE;
116	
117	const DEDUCTIBLE_PER_INCIDENT = 100;
118	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
119	
120	const insuranceSumOf = (items: Item[]): number =>
121	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
122	
123	const totalReimbursementOf = (incident: Incident, insuredItems: Item[]): number =>
124	  incident.damages.reduce(
125	    (total, damage) => total + reimbursementForDamage(damage, insuredItems),
126	    0,
127	  );
128	
129	// A policy is created by a quote step; claims refer back to it by that step's
130	// index and draw down a shared cap.
131	type Policy = { items: Item[]; cap: number; paidOut: number };
132	
133	const policyFor = (items: Item[]): Policy => ({
134	  items,
135	  cap: insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
136	  paidOut: 0,
137	});
138	
139	const DEEP_ENCHANTMENT_LEVEL = 8;
140	const VOLATILE_REIMBURSEMENT_RATE = 0.5;
141	const FULL_REIMBURSEMENT_RATE = 1;
142	
143	// A separate rule from the risk surcharge's HIGH_ENCHANTMENT_LEVEL, at its own
144	// threshold: that one prices a policy, this one settles a claim.
145	const isDeeplyEnchanted = (item: Item): boolean =>
146	  (item.enchantment ?? 0) >= DEEP_ENCHANTMENT_LEVEL;
147	
148	const DRAGON_MATERIAL = "dragon";
149	
150	const isDragonMade = (item: Item): boolean => item.material === DRAGON_MATERIAL;
151	
152	// Deep enchantment makes an item volatile — except dragon material, which is
153	// impervious to it.
154	const isVolatile = (item: Item): boolean =>
155	  isDeeplyEnchanted(item) && !isDragonMade(item);
156	
157	// The MHPCO reimburses only half the damage to a volatile item.
158	const reimbursementRateOf = (item: Item): number =>
159	  isVolatile(item) ? VOLATILE_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
160	
161	const reimbursementForDamage = (damage: Damage, insuredItems: Item[]): number => {
162	  const damagedItem = insuredItems.find((item) => item.type === damage.itemType);
163	
164	  return (
165	    damage.amount *
166	    (damagedItem ? reimbursementRateOf(damagedItem) : FULL_REIMBURSEMENT_RATE)
167	  );
168	};
169	
170	// Read fresh on each side of the draw-down below: the same expression means
171	// the ceiling before paying out and the reported balance after.
172	const remainingCapOf = (policy: Policy): number => policy.cap - policy.paidOut;
173	
174	// Settling a claim draws down the policy's cap, so the policy is mutated here
175	// rather than returned alongside the result.
176	const settleClaim = (policy: Policy, incident: Incident): ClaimResult => {
177	  // Damage at or below the deductible pays nothing; it never refunds cap.
178	  const claimed = Math.max(
179	    totalReimbursementOf(incident, policy.items) - DEDUCTIBLE_PER_INCIDENT,
180	    0,
181	  );
182	  // A policy pays out at most its cap, however much damage is claimed.
183	  const payout = Math.min(claimed, remainingCapOf(policy));
184	
185	  policy.paidOut += payout;
186	  return { payout, remainingCap: remainingCapOf(policy) };
187	};
188	
189	// Only quote steps take out a contract, so the contract number advances
190	// independently of the step number: an intervening claim must not consume one.
191	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
192	  const policies = new Map<number, Policy>();
193	  let contractIndex = 0;
194	
195	  const quote = (step: QuoteStep, stepIndex: number): QuoteResult => {
196	    policies.set(stepIndex, policyFor(step.items));
197	    const premium = premiumFor(
198	      step.items,
199	      policyFactorOf(scenario.customer, contractIndex),
200	    );
201	
202	    contractIndex += 1;
203	    return { premium };
204	  };
205	
206	  const results = scenario.steps.map((step, stepIndex): Result =>
207	    step.op === "claim"
208	      ? settleClaim(policies.get(step.policy)!, step.incident)
209	      : quote(step, stepIndex),
210	  );
211	
212	  return { results };
213	};
